// Original coaching cards: diagrams are examples, not club formation instructions.
const conceptScenes={
 scan:{hook:'Look first. Find your next move.',caption:'You spot the defender before the pass arrives. Receive toward the free side.',a:[75,210],b:[185,140],d:[235,110],path:'M85 205 L173 148',run:'M185 140 L125 100'},
 touch:{hook:'Your first touch buys you time.',caption:'Pressure is on your right. A touch left keeps the ball away from the defender.',a:[75,210],b:[185,140],d:[230,140],path:'M85 205 L173 148',run:'M185 140 L125 115'},
 pass:{hook:'Pass where they are going.',caption:'Your teammate is moving forward. Lead them into the open space instead of passing behind.',a:[80,215],b:[215,150],d:[150,170],path:'M85 205 L215 90',run:'M215 150 L215 90'},
 support:{hook:'Pass. Move. Help again.',caption:'After your pass, move to a new angle so your teammate has a return option.',a:[80,215],b:[215,145],d:[150,175],path:'M90 210 L202 150',run:'M80 215 L85 110'},
 cross:{hook:'Look up before the final ball.',caption:'You are wide. Find the arriving teammate with a cutback instead of crossing without looking.',a:[270,85],b:[160,190],d:[180,75],path:'M265 90 L160 150',run:'M160 190 L160 150'},
 turn:{hook:'You do not always have to turn.',caption:'A defender is tight behind you. Set the ball back to your teammate, then move into space.',a:[80,215],b:[180,145],d:[185,115],path:'M175 150 L90 208',run:'M180 145 L240 190'}
};
function conceptGraphic(id){const c=conceptScenes[id];if(!c)return '';const dot=(p,label,color)=>`<circle cx="${p[0]}" cy="${p[1]}" r="17" fill="${color}" stroke="white" stroke-width="2"/><text x="${p[0]}" y="${p[1]+5}" text-anchor="middle" font-size="11" fill="white">${label}</text>`;return `<figure class="concept-graphic"><figcaption><strong>${c.hook}</strong></figcaption><svg viewBox="0 0 340 280" role="img" aria-label="${escapeHTML(c.caption)}"><defs><marker id="arrow${id}" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#ffe493" stroke-width="1.4"/></marker></defs><rect width="340" height="280" rx="18" fill="#174f40"/><rect x="18" y="18" width="304" height="244" fill="none" stroke="#ffffff50"/><path d="M120 18 V55 H220 V18" fill="none" stroke="#ffffff70"/>${dot(c.a,'A','#63288c')}${dot(c.b,'B','#63288c')}${dot(c.d,'D','#c44720')}<path d="${c.path}" fill="none" stroke="#ffe493" stroke-width="3" marker-end="url(#arrow${id})"/><path d="${c.run}" fill="none" stroke="#ffe493" stroke-width="3" stroke-dasharray="6 5" marker-end="url(#arrow${id})"/></svg><p>${c.caption}</p><small>A / B: teammates · D: defender<br>Solid arrow: ball · dashed: player movement</small></figure>`}
const visualFocus=focusStep;focusStep=function(){visualFocus();if(step===0&&conceptScenes[prefs().focus])hub.querySelector('.focus-card h1').insertAdjacentHTML('afterend',conceptGraphic(prefs().focus))};
const whyExercise={
 'Squat to a chair':['Build control through your hips and legs.','Think: sit down quietly, then stand tall. Do not drop onto the chair.'],
 'Dumbbell floor press':['Practice controlled pushing with a supported body position.','Lower gently until your upper arms touch the floor. Press without bouncing.'],
 'Supported one-arm row':['Build upper-back strength while keeping your trunk steady.','Imagine putting the dumbbell into your back pocket. Keep both shoulders level.'],
 'Glute bridge':['Practice using your hips while keeping your back comfortable.','Lift until shoulders, hips and knees make a gentle line—not a big back arch.'],
 'Suitcase hold':['Practice staying upright against a sideways load.','Imagine balancing a cup on your head. Keep breathing.'],
 'Supported split squat':['Practice leg strength and balance in a staggered stance.','Use your support and lower slowly, like an elevator.'],
 'Incline push-up':['Build pushing strength at a difficulty you can control.','Move your chest and hips together. A higher surface is easier.'],
 'Calf raise':['Strengthen the lower legs through a controlled rise and lowering.','Go up smoothly and lower slowly; hold support for balance.'],
 'Dead bug heel taps':['Practice moving your legs without losing trunk control.','Lower only as far as you can without arching your back.']};
const trainingRender=render;render=function(){trainingRender();document.body.classList.toggle('workout-active',section==='strength'&&!document.body.classList.contains('hub-mode'));if(section==='strength'){document.querySelectorAll('#cards .exercise').forEach(card=>{const item=whyExercise[card.querySelector('h3')?.textContent];if(item&&!card.querySelector('.exercise-why'))card.insertAdjacentHTML('beforeend',`<details class="exercise-why"><summary>Why this helps · example</summary><p>${item[0]}</p><p>${item[1]}</p><p>Use the demonstration above. An adult qualified to teach lifting should check your form before adding weight.</p></details>`)});}};
const trainingHub=showHub;showHub=function(page='Today'){document.body.classList.remove('workout-active');trainingHub(page);if(page==='Today')hub.querySelector('.quiet-home').insertAdjacentHTML('afterend','<button class="quiet-lesson" data-training-plan>My workout plan <span>→</span></button>');if(page==='Learn')hub.querySelector('.quiet-heading').insertAdjacentHTML('afterend',`<details class="quiet-collection"><summary>Six visual starters <span>See the idea</span></summary>${Object.entries(conceptScenes).map(([id,c])=>`<button class="quiet-lesson" data-focus="${id}">${c.hook} →</button>`).join('')}</details>`)};
function trainingPlan(){document.body.classList.remove('lesson-mode');hub.innerHTML=`<button data-hub="Today">← Today</button><h1>${escapeHTML(data.names[player])}’s training plan</h1><p>${player===0?'Connect your first touch to a winger’s next pass or move.':'Build comfortable control, then look up to find a teammate.'}</p><section class="panel"><h2>Learn & prepare</h2><p>Team practice is the main session. Review one cue first. Optional Strength A only when recovered, with adult instruction and enough space from practice to stay fresh.</p><button data-session="A">Open Strength A</button></section><section class="panel"><h2>Ball & decisions</h2><p>Use the week’s idea at team practice. If fresh, try the focus drill as preparation, not an extra conditioning session.</p><button data-start>My focus drill</button><button data-old="soccer">Ball sessions & demonstrations</button></section><section class="panel"><h2>Build or recover</h2><p>No game within 24 hours and feeling recovered? Use Strength B. Game tomorrow, tournament or tired legs? Choose lesson review and recovery instead.</p><button data-session="B">Open Strength B</button><button data-start>Review my idea</button></section><details class="panel"><summary>How to use the beginner workouts</summary><p>Start with one technique set at the listed repetitions. Rest 60–90 seconds between sets, longer if needed. Learn without weight first; a qualified adult should check lifting technique. Your brother can practice beside you, but is not your lifting supervisor.</p><p>Use your own comfortable load. Finish with good form and effort left over. Repeat this foundation for two weeks; add a second set only after adult review, comfortable recovery and reliable technique. Do not add weight just because a week has passed.</p><p>Both players are new to lifting, so age alone does not justify a heavier program. Soccer examples differ; strength progresses by control and recovery.</p><p>Warm up with easy movement and rehearse the exercises without weights. Finish with easy walking. Stop for pain. Team practices and matches already contribute to stamina; no added treadmill sprint sessions here.</p><a target="_blank" rel="noopener" href="https://www.healthychildren.org/English/news/Pages/Guidance-on-Resistance-Training-for-Children.aspx">Parent reference: AAP youth resistance training guidance</a></details>`;window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.trainingPlan!==undefined)trainingPlan();if(b.dataset.session){day=b.dataset.session;openLegacy('strength');document.body.classList.add('workout-active')}});
showHub('Today');
